{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "16-Acetyl-gitoxin, an acetylated steroid-like cardiac glycoside, showed 98.6% absolute oral bioavailability in healthy volunteers, demonstrating that acetylated steroid/triterpenoid scaffolds can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Chenodeoxycholic acid, a steroid carboxylic acid with hydroxyl groups, showed 81% systemic bioavailability at 750 mg and complete bioavailability at lower doses, supporting high oral absorption for carboxylated steroid-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Methylprednisolone sodium succinate, a steroid ester/carboxylic acid prodrug, had systemic bioavailability of 0.82 relative to IV, supporting high F for a steroid with carboxyl/ester functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlormadinone acetate, a steroid acetate, showed approximately 100% oral bioavailability, indicating that an acetate on a steroid core does not inherently cause low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Medroxyprogesterone acetate had low oral bioavailability (<15%) in humans, a counterexample among steroid acetates, but its progestin-specific first-pass metabolism is less transferable to the fusidane acid scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Acetyl-11-keto-boswellic acid, a pentacyclic triterpenoid acid with an acetate, had poor oral bioavailability, but its pentacyclic lipophilic acid structure is less transferable to the tetracyclic fusidane scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fusidic acid, a tetracyclic steroidal antibiotic with a carboxylic acid, hydroxyls, and an acetate. The most transferable evidence from steroid/triterpenoid acids and acetylated steroid cores (bile acids, methylprednisolone succinate, chlormadinone acetate, 16-acetyl-gitoxin) consistently supports high oral bioavailability (F ≥ 20%). The low-F examples are less structurally transferable (progestin acetate, pentacyclic boswellic acid, glycoside). Therefore predict high.",
  "evidence_gaps": [
    "No direct fusidic acid bioavailability record is present in the evidence set; all analogues have low Morgan similarity (<0.27).",
    "No experimental data specific to the prenyl side chain or the balance of solubility versus permeability for this exact scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

